import {
  createContext, useCallback, useContext, useMemo, useRef, useState,
  type ReactNode,
} from 'react';
import { Dialog } from './Dialog';

type ConfirmAPI = {
  openConfirm: <A extends unknown[]>(
    fn: (...args: A) => unknown,
    content?: ReactNode,
  ) => (...args: A) => boolean;
};

const ConfirmContext = createContext<ConfirmAPI | null>(null);

export function ConfirmProvider({
  children,
  defaultContent = '정말 실행할까요?',
}: {
  children: ReactNode;
  defaultContent?: ReactNode;
}) {
  const task = useRef<(() => unknown) | null>(null);
  const busy = useRef(false);
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [content, setContent] = useState<ReactNode>(defaultContent);
  const [error, setError] = useState<string | null>(null);

  const close = useCallback(() => {
    if (busy.current) return;
    task.current = null;
    setOpen(false);
    setError(null);
  }, []);

  const apply = useCallback(async () => {
    if (busy.current || !task.current) return;
    const run = task.current;
    busy.current = true;
    setPending(true);
    setError(null);
    try {
      await run();
      task.current = null;
      setOpen(false);
    } catch {
      setError('처리 결과를 확인하지 못했습니다. 상태를 확인한 뒤 다시 시도해주세요.');
    } finally {
      busy.current = false;
      setPending(false);
    }
  }, []);

  const openConfirm = useCallback(
    <A extends unknown[],>(
      fn: (...args: A) => unknown,
      customContent?: ReactNode,
    ) => (...args: A): boolean => {
      if (task.current !== null || busy.current) return false;
      task.current = () => fn(...args);
      setContent(customContent === undefined ? defaultContent : customContent);
      setError(null);
      setOpen(true);
      return true;
    },
    [defaultContent],
  );

  const value = useMemo(() => ({ openConfirm }), [openConfirm]);
  return (
    <ConfirmContext.Provider value={value}>
      {children}
      <Dialog open={open} onClose={close}>
        <div aria-busy={pending}>
          {content}
          {error && <p role="alert">{error}</p>}
          <button type="button" disabled={pending} onClick={close}>취소</button>
          <button type="button" disabled={pending} onClick={apply}>
            {pending ? '처리 중…' : '확인'}
          </button>
        </div>
      </Dialog>
    </ConfirmContext.Provider>
  );
}

export function useConfirm<A extends unknown[]>(
  fn: (...args: A) => unknown,
  content?: ReactNode,
) {
  const context = useContext(ConfirmContext);
  if (context === null) {
    throw new Error('useConfirm은 ConfirmProvider 안에서 사용해야 합니다.');
  }
  return useMemo(
    () => context.openConfirm(fn, content),
    [context, fn, content],
  );
}

